     ...
     return 0;
 }

==== Bit ''ERR_FLAG'' (dim: ''1 bit'', type: ''R'', mask: ''0x00000002'', reset: ''0'') ====

If there was a Wishbone error (wire ''w_err'' on Wishbone bus) or an overflow in the ''Master'' FIFO this Flag is set high. The Flag will be reset when new frame starts.

Example code:

 #define MASK_FLAG_ERR 0x00000002
 /* Size image: 640x480 colors (2 byte).
 #define IMAGE_SIZE    (640*480*2)
 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF      0x00000000
 #define STATE_OFF     0x00000004
 #define FLAG_OFF      0x00000008
 #define CNTR2_OFF     0x00000010
 #define DIV_OFF       0x00000014
 #define COUNT_OFF     0x00000018

 int main(void) {
     /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
     unsigned long *register_flag = (CAMERA_BASE_ADDRESS + FLAG_OFF);
     unsigned long bit_err_flag;
     ...
     /* Capture an image */
     ...
     /* Read bit ERR_FLAG */
     bit_err_flag = *register_flag & MASK_ERR_FLAG;
     if (bit_err_flag) {
         /* There was a error on wishbone and/or overflow data fifo */
     } else {
         /* There was not error */
     }     
     ...
     return 0;
 }

==== Bit ''IF_FLAG'' (dim: ''1 bit'', type: ''R'', mask: ''0x00000001'', reset: ''0'') ====

It is set at the end of an acquisition. In other words, when a frame has been completely written in the memory the flag change value from 0 logic to 1 logic. The Flag will be reset when new frame starts.

:#''from 0 to 1'' => The ''mico32_camera'' switches from ''Writing Last'' state to ''Idle'' state or from ''Writing'' state to ''Waiting Next'' state. If ''IE_FLAG = 1'b1'' an interrupt is raised.
:#''0'' => No frame has been completed.

Example code:

 #define MASK_IF_FLAG  0x00000001
 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF      0x00000000
 #define STATE_OFF     0x00000004
 #define FLAG_OFF      0x00000008
 #define CNTR2_OFF     0x00000010
 #define DIV_OFF       0x00000014
 #define COUNT_OFF     0x00000018

 int main(void) {
    /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
    unsigned long *register_flag = (CAMERA_BASE_ADDRESS + FLAG_OFF);
    unsigned long bit_if_flag;
    ...
    /* Start capture image */
    ...
    /* Read bit IF_FLAG for end capture */
    do {
        ...
        bit_if_flag = *register_flag & MASK_IF_FLAG;
        ...
    } while (!bit_if_flag);
    ...
    return 0;
 }

=== ''CNTR1'' register (dim: ''32 bits'', type: ''W'', offset: ''0x0000000C'') ===

This register has three bits:

{| class="wikitable"
|+CNTR1 register
! Bit31
! Bit30
! ...
! Bit2
! Bit1
! Bit0
|-
| -
| -
| ...
| CNTR_RST
| IF_RESET
| CNTR_S
|}

==== Bit ''CNTR_START'' (dim: ''1 bit'', type: ''W'', mask: ''0x00000001'', reset: ''-'') ====

:#When the programmer writes ''1 logic'' in this bit the component starts an new acquisition.

Example code:

 #define MASK_CNTR_START  0x00000001
 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF         0x00000000
 #define STATE_OFF        0x00000004
 #define FLAG_OFF         0x00000008
 #define CNTR1_OFF        0x0000000C
 #define CNTR2_OFF        0x00000010
 #define DIV_OFF          0x00000014
 #define COUNT_OFF        0x00000018

 int main(void) {
    /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
    unsigned long *register_cntr1 = (CAMERA_BASE_ADDRESS + CNTR1_OFF);
    ...
    /* Start capture image */
    *register_cntr1 = MASK_CNTR_START;
    /* Read bit IF_FLAG for end capture */
    do {
        ...
        bit_if_flag = *register_flag & MASK_IF_FLAG;
        ...
    } while (!bit_if_flag);
    ...
    return 0;
 }

==== Bit ''IF_RESET'' (dim: ''1 bit'', type: ''W'', mask: ''0x00000002'', reset: ''-'') ====

:#The programmer writes “1” logic for acknowledge interrupt.

Example code:

 #define MASK_CNTR_START  0x00000001
 #define MASK_IF_RESET    0x00000002
 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF         0x00000000
 #define STATE_OFF        0x00000004
 #define FLAG_OFF         0x00000008
 #define CNTR1_OFF        0x0000000C
 #define CNTR2_OFF        0x00000010
 #define DIV_OFF          0x00000014
 #define COUNT_OFF        0x00000018

 /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
 unsigned long *register_cntr1 = (CAMERA_BASE_ADDRESS + CNTR1_OFF);

 /* Prototype Interrupt handler end image acquisition */
 void frame_isr(void);

 int main(void) {
    /* Record handler camera interrupt 
       See: LatticeMico32 Software Developer User Guide, on Lattice Semiconductor Web site*/
    /* Enable Mico32 external interrupt (in this case from mico32_camera). */
    MicoEnableInterrupt(mico32_camera_irq);	
    MicoRegisterISR(mico32_camera_irq, NULL, frame_isr);
    ...
    /* Start capture image */
    *register_cntr1 = MASK_CNTR_START;
    ...
    return 0;
 }

 /* Interrupt handler end image acquisition */
 void frame_isr(void) {
    ...
    /* Acknowledge interrupt */
    *register_cntr1 = MASK_IF_RESET;
    ...    
 }

==== Bit ''CNTR_RST'' (dim: ''1 bit'', type: ''W'', mask: ''0x00000004'', reset: ''-'') ====

:#If the programmer writes ''1 logic'' in this bit, the component switches to ''Reset'' state.

Example code:

 #define MASK_CNTR_RST    0x00000004
 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF         0x00000000
 #define STATE_OFF        0x00000004
 #define FLAG_OFF         0x00000008
 #define CNTR1_OFF        0x0000000C
 #define CNTR2_OFF        0x00000010
 #define DIV_OFF          0x00000014
 #define COUNT_OFF        0x00000018

 int main(void) {
   /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
   unsigned long *register_state = (CAMERA_BASE_ADDRESS + STATE_OFF);
   unsigned long *register_cntr1 = (CAMERA_BASE_ADDRESS + CNTR1_OFF);
   unsigned lond state;

   /* Reset mico32_camera */
   *register_cntr1 = MASK_CNTR_RST;
   /* Waiting IDLE mico32_camera state */
    do {
         state = *register_state;
         ...
    while (state != IDLE);  
   ...
   return 0;
 }

=== ''CNTR2'' register (dim: ''32 bits'', type: ''R/W'', offset: ''0x00000010'') ===

This register has one bit:

{| class="wikitable"
|+CNTR2 register
! Bit31
! Bit30
! ...
! Bit2
! Bit1
! Bit0
|-
| -
| -
| ...
| -
| -
| IE_FLAG
|}

==== Bit ''IE_FLAG'' (dim: ''1 bit'', type: ''R/W'', mask: ''0x00000001'', reset: ''0'') ====

:#The programmer writes “1” logic for interrupt camera enable (mico32_camera is enabled to send an interrupt).

Example code:

 #define MASK_IE_FLAG     0x00000001
 #define MASK_CNTR_START  0x00000001
 #define MASK_IF_RESET    0x00000002
 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF         0x00000000
 #define STATE_OFF        0x00000004
 #define FLAG_OFF         0x00000008
 #define CNTR1_OFF        0x0000000C
 #define CNTR2_OFF        0x00000010
 #define DIV_OFF          0x00000014
 #define COUNT_OFF        0x00000018

 /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
 unsigned long *register_cntr1 = (CAMERA_BASE_ADDRESS + CNTR1_OFF);
 unsigned long *register_cntr2 = (CAMERA_BASE_ADDRESS + CNTR2_OFF);

 /* Prototype Interrupt handler end image acquisition */
 void frame_isr(void);

 int main(void) {
    /* Record handler camera interrupt 
       See: LatticeMico32 Software Developer User Guide, on Lattice Semiconductor Web site*/
    /* Enable Mico32 external interrupt (in this case from mico32_camera). */
    MicoEnableInterrupt(mico32_camera_irq);	
    MicoRegisterISR(mico32_camera_irq, NULL, frame_isr);
    /* mico32_camera is enabled to send an interrupt */
    *register_cntr2 = MASK_IE_FLAG;
    ...
    /* Start capture image */
    *register_cntr1 = MASK_CNTR_START;
    ...
    return 0;
 }

 /* Interrupt handler end image acquisition */
 void frame_isr(void) {
    ...
    /* Acknowledge interrupt */
    *register_cntr1 = MASK_IF_RESET;
    ...    
 }

== How to Interface a CAL Netlist to System Actors ==
To interface a CAL Netlist with an actor few steps are needed:
* Create a Netlist in the CAL environment with the needed number of input and output ports
* Build a wrapper in Verilog (or VHDL) that connects the netlist with the required system actors

== How to Build a CAL Project with ispLEVER ==
First you must to have a Cal project with System Actors for FPG-EYE. See [[Create a Cal project with System Actors]] for instructions on how to do it.
To build an ispLEVER CAL project we have to:
* Open ispLEVER and click on new project. [[File:new_project.png|center|thumb|200px| Click on "Open Project"]]
* In the following window choose the project name and the its destination path. Please remember to select "Mixed Verilog/VHDL" for the option "Design Entry Type". [[File:name_project.png|center|thumb|200px|Add "Name Project"]]
* In the following window we have to select the device. For the FPG-EYE board we must use:
** Family: LatticeXP2;
** Device: LFXP2-17E;
** Speed grade: 5;
** Package type: PQFP208;
** Operating conditions: Commercial;
** PartName: LFXP2-17E-5QN208C. [[File:select_device.png|center|thumb|200px|"Select Device"]]
* Finally by clicking the End button [[File:add_source.png|center|thumb|200px|"Add Source"]] the following window will be displayed: [[File:isp_lever.png|center|thumb|200px|ispLEVER]]
* To import <tt>lattice_cal.vhdl</tt> the library (<tt>svn-cal/hw/trunk/lib_vhdl</tt>) we have to right click on device and select "Import...". [[File:import_file.png|center|thumb|200px|Import file]]
* In the file window we can now select the file <tt>lattice_cal.vhdl</tt> [[File:lib_vhdl.png|center|thumb|200px|Import the file "lattice_cal.vhdl"]]
* Now by right clicking the lattice_cal.vhdl we can select "Library Name" [[File:library_name.png|center|thumb|200px|Select "Library Name"]]
* In the Box "VHDL Library Name" we can insert the namespace <tt>SystemBuilder</tt>[[File:system_builder.png|center|thumb|200px|Write: SystemBuilder]]
* Each file created by the CAL compiler has an undefined module FD. This module is a D-FF (flip flop) declared in the xilinx library. This is part of a small reset synchronizer circuit. You have to remove this part because the Lattice software does not recognize it.<br/> There is a Perl script <tt>main_modify.pl</tt> that searches these FD instances in Verilog files and replaces them with a reset synchronizer. You can run this Perl script with the top level VHDL file as input. Before executing the Perl script, please check that all generated files are in the same folder. If the top level generated file name is <tt>main_nw.vhd</tt>, we can issue <tt>perl main_modify.pl main_nw</tt>.<br/> The script will produce a *_mod.v file for each parsed Verilog file.
* After importing the files related to the various actors (LED, camera, and those related to our CAL netlist), a constraint file describing the connection between FPGA pins and logic blocks must be created. An example of these constraints can be found in "svn-cal\hw\trunk\examples\example7\isp_lever\example7.lpf"
* We can finally compile the project, thus obtaining a binary JED file to program the FPG-EYE board.
* See [[Programming the FPG-EYE board]] for instructions on how to download the JED file onto the board

== Introduction ==
This document is for programmers for writing drivers based on ''mico32_camera''. For details refer follow figure:

[[File:platform_with_camera.png|center|thumb|200px|''mico32_camera'' values in the platform]]

== Registers of the ''mico32_camera'' ==

Following registers are visible by the program:

{| class="wikitable"
|-
! Register Name
! Offset
! Num. Bits
! Type
|-
| ADDR
| 0x0
| 32
| R/W
|-
| STATE
| 0x04
| 32
| R
|-
| FLAG
| 0x08
| 32
| R
|-
| CNTR1
| 0x0C
| 32
| W
|-
| CNTR2
| 0x10
| 32
| R/W
|-
| DIV
| 0x14
| 32
| R/W
|-
| COUNT
| 0x18
| 32
| R/W
|}

All register are 32 bits. Some registers are read-only (''STATE'' and ''FLAG''), only one register is write-only (''CNTR1''), the remaining registers are read-write (''ADDR'', ''CNTR2'', ''DIV'' and ''COUNT'').

=== C code example to read a value from register ===

To get a register value (''ADDR'', ''STATE'', ''FLAG'', ''CNTR2'', ''DIV'' and ''COUNT''):

    /* Offsets mico32_camera resister from address_base */ 
    #define ADDR_OFF    0x00000000
    #define STATE_OFF   0x00000004
    #define FLAG_OFF    0x00000008
    #define CNTR2_OFF   0x00000010
    #define DIV_OFF     0x00000014
    #define COUNT_OFF   0x00000018

    int main(void) {
        /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
        unsigned long *register = (CAMERA_BASE_ADDRESS + COUNT_OFF);
        unsigned long count_value;
        ...
        /* Read count register. */
        count_value = *register;     
        ...
        return 0;
    }

=== C code example to write a value to register ===
To set a register value (''ADDR'', ''CNTR1'', ''DIV'' and ''COUNT''):

   #define ADDR_VALUE  0x00010000
   /* Offsets mico32_camera resister from address_base */ 
   #define ADDR_OFF    0x00000000
   #define STATE_OFF   0x00000004
   #define FLAG_OFF    0x00000008
   #define CNTR2_OFF   0x00000010
   #define DIV_OFF     0x00000014
   #define COUNT_OFF   0x00000018

   int main(void) {
       /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
       unsigned long *register = (CAMERA_BASE_ADDRESS + ADDR_OFF);
       ...
       /* Write addr register. */
       *register = ADDR_VALUE;     
       ...
       return 0;
   }

== Registers description ==
The mico32_camera has seven registers. The functionality of each register is as described below.

=== ''ADDR'' register (dim: ''32 bits'', type: ''R/W'', offset: ''0x00'', reset: ''0x00000000'') ===

When ''mico32_camera'' starts a new image acquisition, it stores the streaming camera data (''32 bits'' at time) in the memory. After every data write in memory, the ''mico32_camera'' increments the internal pointer for next data write. The address base where the data writing begins is written in ''ADDR'' register. 

{| class="wikitable"
|+ADDR register
! Bit31
! Bit30
! ...
! Bit2
! Bit1
! Bit0
|-
| ADDR31
| ADDR30
| ...
| ADDR2
| ADDR1
| ADDR0
|}

Example code:

  #define ADDR_VALUE  0x00010000
  /* Offsets mico32_camera resister from address_base */ 
  #define ADDR_OFF    0x00000000
  #define STATE_OFF   0x00000004
  #define FLAG_OFF    0x00000008
  #define CNTR2_OFF   0x00000010
  #define DIV_OFF     0x00000014
  #define COUNT_OFF   0x00000018

  int main(void) {
      /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
      unsigned long *register = (CAMERA_BASE_ADDRESS + ADDR_OFF);
      ...
      /* Write addr register. */
      *register = ADDR_VALUE;     
      ...
      return 0;
  }

=== ''STATE'' register (dim: ''32 bits'', type: ''R'', offset: ''0x04'') ===

The ''STATE'' register stores ''mico32_component's'' internal state information:

{| class="wikitable"
|+STATE register
! Bit31
! Bit30
! ...
! Bit3
! Bit2
! Bit1
! Bit0
|-
| -
| -
| ...
| -
| STATE2
| STATE1
| STATE0
|}

Bits ''STATE2'', ''STATE1'' and ''STATE0'' (''STATE_S'') (dim: ''3 bits'', type: ''R'', offset: ''0x00'', reset: ''000''). Returns the state of the component.

:#''000 => Reset''
:#''001 => Idle''
:#''010 => Waiting First''
:#''011 => Waiting Next''
:#''100 => Copying''
:#''101 => Copying Last''

Example code:

 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF    0x00000000
 #define STATE_OFF   0x00000004
 #define FLAG_OFF    0x00000008
 #define CNTR2_OFF   0x00000010
 #define DIV_OFF     0x00000014
 #define COUNT_OFF   0x00000018
 /* mico32_camera states */
 #define RESET          0
 #define IDLE           1
 #define WAITING_FIRST  2
 #define WAITING_NEXT   3
 #define COPYING        4
 #define COPYING_LAST   5

 int main(void) {
     /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
     unsigned long *register = (CAMERA_BASE_ADDRESS + STATE_OFF);
     unsigned long state;
     ...
     /* Waiting IDLE mico32_camera state */
     do {
          state = *register;
          ...
     while (state != IDLE);     
     ...
     return 0;
 }

=== ''FLAG'' register (dim: ''32 bits'', type: ''R'', offset: ''0x08'') ===

The ''FLAG'' register is composed of :

{| class="wikitable"
|+STATE register
! Bit31
! Bit30
! ...
! Bit2
! Bit1
! Bit0
|-
| -
| -
| ...
| -
| SIZE_ERR
| ERR_FLAG
| IF_FLAG
|}

==== Bit ''SIZE_ERR'' (dim: ''1 bit'', type: ''R'', mask: ''0x00000004'', reset: ''0'') ====

If the image's size in bytes is different from the value register count, this bit is set. The control is turned off when the value register count is set to 0 (zero).

Example code:

 #define MASK_SIZE_ERR 0x00000004
 /* Size image: 640x480 colors (2 byte).
 #define IMAGE_SIZE    (640*480*2)
 /* Offsets mico32_camera resister from address_base */ 
 #define ADDR_OFF      0x00000000
 #define STATE_OFF     0x00000004
 #define FLAG_OFF      0x00000008
 #define CNTR2_OFF     0x00000010
 #define DIV_OFF       0x00000014
 #define COUNT_OFF     0x00000018

 int main(void) {
     /* Macro CAMERA_BASE_ADDRESS from system_conf.h */
     unsigned long *register_count = (CAMERA_BASE_ADDRESS + COUNT_OFF);
     unsigned long *register_flag = (CAMERA_BASE_ADDRESS + FLAG_OFF);
     unsigned long bit_size_err;
     ...
     /* With a write in count register we enable the image size control. */
     *register_count = IMAGE_SIZE;
     ...
     /* Capture an image */
     ...
     /* Read bit SIZE_ERR */
     bit_size_err = *register_flag & MASK_SIZE_ERR;
     if (bit_size_err) {
         /* There was a size error */
     } else {
         /* There was not size error */
     }     
     ...
     return 0;
 }

==== Bit ''ERR_FLAG'' (dim: ''1 bit'', type: ''R'', mask: ''0x00000002'', reset: ''0'') ====

If there was a Wishbone error (wire ''w_err'' on Wishbone bus) or an overflow in the ''Master'' FIFO this Flag is set high. The Flag will be reset when new frame starts.

Example code:

 #define MASK_FLAG_ERR 0x00000002
 /* Size image: 640x480 colors (2 byte).
 #define IMAGE_SIZE    (640*480*2)
 /* Offsets mico32_camera resister from address_base */ 
